declare(strict_types=1);define('PROJECT_ROOT',dirname(__DIR__));require PROJECT_ROOT.'/vendor/autoload.php';require_once PROJECT_ROOT.'/core/Storage.php';use App\Services\Institution\SocialInsuranceService;$db=Core\DbPdo::conn();$ids=$db->query('SELECT id FROM user_employees ORDER BY id LIMIT 20')->fetchAll(PDO::FETCH_COLUMN);if(!$ids)throw new RuntimeException('성능측정 대상 직원이 없습니다.');while(count($ids)<20)$ids[]=$ids[count($ids)%count($ids)];$questions=fn()=>(int)$db->query("SHOW SESSION STATUS LIKE 'Questions'")->fetch(PDO::FETCH_ASSOC)['Value'];$before=$questions();$started=hrtime(true);$data=(new SocialInsuranceService($db))->batchForMonth(array_values(array_unique($ids)),date('Y-m'));$elapsed=(hrtime(true)-$started)/1000000;$after=$questions();$result=['success'=>true,'requested_employee_count'=>20,'unique_employee_count'=>count(array_unique($ids)),'coverage_count'=>count($data['coverages']),'basis_count'=>count($data['bases']),'query_count_delta'=>$after-$before-1,'sql_time_ms'=>round($elapsed,3),'payload_bytes'=>strlen(json_encode($data,JSON_UNESCAPED_UNICODE)),'n_plus_one'=>($after-$before-1)>2];echo json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;if($result['n_plus_one'])exit(1);
